(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.28)*18 + Math.sin(x*0.015+t*0.33)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8 + Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.45)*8 + Math.sin((x+w1x)*0.019-t*0.35)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, -0.3],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.7],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, -0.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, -0.6],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+2)*50, 0.11, 2.1, 0.2],
    [400+Math.cos(t*0.45+1)*60, 200+Math.sin(t*0.65+4)*55, 0.05, 1.8, -0.4]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp+ph);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5+ph*0.5);
    cS += Math.sin(d*f*1.3-t*sp*0.4+ph*2)*0.5;
  }
  const act=aS/8, inh=iS/8, cross=cS/8;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*1.05))/2
    + Math.sin((sx+sy)*0.1+t*2.2)*0.25 + Math.sin((sx-sy)*0.08-t*1.8)*0.25
    + Math.sin(sx*0.06*sy*0.04+t*0.9)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3-t*1.4);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral = (sp1+sp2)*0.35+sp3;
  const vort1 = Math.sin(dist*0.03-ang*6+t*0.8)*Math.exp(-dist*0.005)*0.3;
  const vort2 = Math.sin(dist*0.04+ang*5-t*1.2)*Math.exp(-dist*0.004)*0.25;
  const cellA = Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.5)*1.6);
  const cellB = Math.tanh((Math.sin(sx*0.18+t*0.3)*Math.cos(sy*0.16-t*0.2))*1.2)*0.5;
  const edge = 1-Math.min(1, Math.abs(cellA)*3)*0.6;
  const reaction = Math.tanh((act-inh*0.65+cross*0.3+bg*0.25+spiral+vort1+vort2)*2.0);
  const cell = (cellA*0.6+cellB*0.4)*0.3;
  const blend = reaction*0.7+cell*0.3;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[10,45,95],[12,85,125],[18,135,145],
    [60,175,150],[180,200,80],[220,170,60],[210,110,55],
    [185,60,65],[120,30,70],[55,15,55],[5,12,55]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const glow = Math.max(0, reaction)*0.15;
  const edgeBoost = edge>0.7?1.1:1.0;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeBoost+glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeBoost+glow*80)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edgeBoost+glow*120)|0)
  ];
}
